from pathlib import Path
P=Path(__file__).resolve().parent
s=(P/'validate.gd').read_text()
s=s.replace('for id in ["crew_lounge","observation_room"]:', 'for id in ["observation_room"]:')
s=s.replace('for sample_mode in range(2):','for test_case in range(12):\n\t\t\tvar sample_mode:int=test_case/6\n\t\t\tvar trigger_stage:String="observation_read_enter" if test_case%6<4 else "observation_read"\n\t\t\tvar trigger_elapsed:float=[.03,.13,.29,.43,.15,.75][test_case%6]')
s=s.replace('controller-native/', 'interrupt-native/')
s=s.replace('var began_foot:Vector2=actor.foot;', 'var interrupted:=false;var reward_before:float=actor.needs["curiosity"];var before_hash:String="";var after_hash:String="";var began_foot:Vector2=actor.foot;')
s=s.replace('for step in range(1100):','for step in range(240):')
s=s.replace('var frame:Texture2D=game.grid_view._get_branforth_frame(game)', '''var trigger_clock:float=11.04-actor.timer if actor.stage=="observation_read" else actor.action_elapsed()
				if not interrupted and actor.stage==trigger_stage and trigger_clock>=trigger_elapsed:
					var original:Texture2D=game.grid_view._get_branforth_frame_source(game)
					before_hash=original.get_image().get_data().hex_encode().sha256_text()
					check(actor.valid_snapshot(actor.snapshot()),"Pre-interruption snapshot admission")
					game.powered_room_cells.erase(cell)
					check(not actor.service_available(game,cell),"Actual room power loss removes service")
					actor.update(game,1.0/60.0)
					var restored:Texture2D=game.grid_view._get_branforth_frame_source(game)
					after_hash=restored.get_image().get_data().hex_encode().sha256_text()
					check(actor.stage=="observation_read_exit" and actor.goal.is_empty(),"Power loss starts tablet stow before rise")
					check(before_hash==after_hash,"Power loss preserves exact current rendered source pixels")
					check(actor.valid_snapshot(actor.snapshot()),"Interrupted stow snapshot admission")
					interrupted=true;previous=""
				var frame:Texture2D=game.grid_view._get_branforth_frame(game)''')
s=s.replace('"%s-mode%d-change%03d.png"%[id,sample_mode,captures]', '"case%02d-mode%d-change%03d.png"%[test_case,sample_mode,captures]')
s=s.replace('"room":id,"mode":sample_mode,','"room":id,"mode":sample_mode,"case":test_case,"triggerStage":trigger_stage,"triggerElapsed":trigger_elapsed,"interrupted":interrupted,"beforeHash":before_hash,"afterHash":after_hash,"sourceHash":game.grid_view._get_branforth_frame_source(game).get_image().get_data().hex_encode().sha256_text(),"tabletExitPose":actor.tablet_exit_pose,')
s=s.replace('check(seen_rise,"Controller completes seated held activity and rises")','check(interrupted and seen_rise,"Interrupted controller stows then rises")\n\t\t\tcheck(actor.needs["curiosity"]>=reward_before,"Cancelled reading earns no completion reward; normal need growth retained")')
s=s.replace('validate-evidence.json','interrupt-evidence.json').replace('validate.gd.uid','interrupt.gd.uid')
s=s.replace('Actual normal NPC update timers after reachable q0 furniture station arrival, held activity/rise and source-change native captures, both gears. Fixed60Hz fixture steps and controlled topology; no autonomous incoming/outgoing travel, interruption, fresh Continue or all-rotation claim.','Actual normal NPC update after reachable q0 South sofa arrival, four partial draw and two held power-loss interruptions per gear; exact source pixel continuity, snapshot admission and fixed physical foot. No fresh disk Continue, autonomous travel or other rotation claim.')
s=s.replace('JAMES SEATED TABLET PHASES:', 'JAMES TABLET INTERRUPTIONS:')
(P/'interrupt.gd').write_text(s)
print('Created twelve-case actual power-loss interruption fixture.')
